"""Independent arithmetic and output comparisons; standalone public consumer."""
exec(compile('"""Independent literal arithmetic; never imports model or reads output.json."""\nimport json,math\n# Literals transcribed from operating/cash budget; independent discount algebra.\nD=[.8315587785944386,.8868913038524103,1.03625088378,1.1255795988969701,1.1896174320099482,2.5067831495110076,2.682423250252361,2.8674243370321326,3.058385692930462,3.251968763933257]\nDM=[.7813093507255398,.6916430039999993,.9874409393799998,1.0730297508903701,1.1338074100603455,2.3554366523318913,2.5294087733574684,2.7110404786834916,2.8973424544911826,3.0853251996492395]\ndef calc(d,np,cash,rate):\n    f=np*1.025*.84375\n    asset=cash-1.443325691208839+.07485824473-.00964602093\n    tv=f/(rate-.025)+asset\n    pv=0\n    for i in range(10):pv+=d[i]*math.pow(1+rate,-i-1)\n    return (pv+tv*math.pow(1+rate,-10))/1.16\nlow=calc(D,4.121347865652231,4.237850198199933,.105)\nhigh=calc(D,4.121347865652231,4.237850198199933,.095)\nmargin=calc(DM,3.9296561722885572,4.039604699784657,.10)\nassert abs(low-23.82537066431751)<1e-10\nassert abs(high-27.977257495776602)<1e-10\nassert abs(margin-24.368799176409947)<1e-10\n# Source arithmetic independent from projection engine.\nassets=14094499893.88;liabilities=2401788652.07\nassert round(assets-liabilities,2)==11692711241.81\nassert round(2607146181.17-1695097493.40,2)==912048687.77\nassert round(12846536412.13+9646020.93,2)==12856182433.06\nprint(json.dumps({\'core_low\':low,\'core_high\':high,\'gross_margin_minus_1pp\':margin,\'source_equity_checks\':\'pass\'},indent=2))\n', __file__, "exec"), {"__file__": __file__, "__name__": "__main__"})
exec(compile("from pathlib import Path\nfrom decimal import Decimal as D,getcontext\nimport json,pathlib\ngetcontext().prec=35\nZ=D(0)\ndef d(v):return D(str(v))\ndef recalc(shift=Z):\n rev=list(map(d,[6.5,4.3,.8,.9]));growth=[[.08,.08,.07,.06,.05],[.12,.12,.10,.08,.06],[.15,.15,.12,.10,.08],[.10,.10,.08,.06,.05]]\n p=d('.57976271516');s=d('1.04693782226')-p;legal=d('9.98198718724');res=d('.4');sl=d(1);debt=d('.23938569609');wc=d('6.05');prev_n=None;prev_need=d('.8');allrows=[]\n for yr in range(1,11):\n  gr=[d(growth[i][yr-1]) for i in range(4)] if yr<=5 else [d([.05,.045,.04,.035,.03][yr-6])]*4\n  rev=[a*(1+b)for a,b in zip(rev,gr)];total=sum(rev);m=[d('.365')+min(yr-1,2)*d('.005'),d('.20')+min(yr-1,3)*d('.01'),d('.30'),d('.33')]\n  n=(sum(a*(b+shift)for a,b in zip(rev,m))-d('.098')*total)*d('.85');newwc=total*d('.49');dw=newwc-wc;need=total*d('.064');dn=need-prev_need\n  da=d([.45,.52,.60,.68,.75][yr-1]) if yr<=5 else d('.75')*d('1.04')**(yr-5)\n  cap=d([1.6,1.6,1.5,1.3,1.2][yr-1]) if yr<=5 else max(da*d('1.05'),da+max(Z,(n-prev_n)/d('.16'))-dw-dn)\n  fcf=n+da-cap-dw;mp=need*d('.625');ms=need*d('.375');start=p+s;fp=max(Z,p-mp)*d('.01');fs=max(Z,s-ms)*d('.01');li=d('.43')*d('.063')*d('.85')*d('.8') if yr==1 else Z;it=debt*d('.04')*d('.85');principal=d('.43') if yr==1 else Z\n  own=(n+da-dw)*d('.8')-cap*d('.45');p+=own+fp+li+principal-it;s+=fcf-own+fs\n  pn=n*d('.8')+fp+li-it;sn=n*d('.2')+fs;pro=min(max(Z,d('.58')-res),max(Z,pn-max(Z,-legal))*d('.1'));res+=pro;legal+=pn-pro;sl+=sn-max(Z,sn)*d('.1')\n  inject=max(Z,ms-s);p-=inject;s+=inject;up=min(max(Z,s-ms),max(Z,sl),max(Z,mp-p));s-=up;p+=up;sl-=up;legal+=up\n  borrow=max(Z,mp-p);p+=borrow;debt+=borrow;repay=min(debt,max(Z,p-mp));p-=repay;debt-=repay\n  desired=max(Z,n+fp+fs+li-it)*d('.35')\n  if yr>=6:desired=max(desired,max(Z,fcf-it)*d('.8'))+d('.2')*max(Z,start-need)\n  extra=min(max(Z,desired-(p-mp)),max(Z,s-ms),max(Z,sl));s-=extra;p+=extra;sl-=extra;legal+=extra\n  dist=min(desired,max(Z,p-mp),max(Z,legal));p-=dist;legal-=dist\n  allrows.append({'year':yr,'nopat':n,'capex':cap,'dividend':dist,'cash_parent':p,'cash_sub':s,'parent_re':legal,'subs_re':sl,'parent_reserve':res,'debt_end':debt,'min_cash':need})\n  wc=newwc;prev_n=n;prev_need=need\n def val(rate):\n  last=allrows[-1];term=last['nopat']*d('1.025')*(1-d('.025')/d('.16'))/(rate-d('.025'))+p+s-last['min_cash']+d('.07485824473')-d('.00964602093')-debt\n  total=sum(x['dividend']/(1+rate)**x['year'] for x in allrows)+term/(1+rate)**10\n  tv5=sum(x['dividend']/(1+rate)**(x['year']-5)for x in allrows if x['year']>5)+term/(1+rate)**5\n  return total/d('1.16'),tv5/d('1.16')\n return allrows,{str(x):val(d(x))for x in [.095,.10,.105]}\nprod=json.load(open(str(Path(__file__).resolve().parent / '2026-Q3-output.json')));checks=[]\nfor name,shift,rows in [('base',Z,prod['cases']['base']['rows']),('margin_minus_1pp',d('-.01'),prod['sensitivity']['gross_margin_minus_1pp']['rows'])]:\n actual,v=recalc(shift);err=[]\n for a,b in zip(actual,rows):\n  for k,x in a.items():\n   if k!='year':err.append(abs(float(x)-b[k]))\n assert max(err)<1e-10,(name,max(err));checks.append({'case':name,'row_checks':len(err),'max_error':max(err),'valuations':{k:[str(x)for x in vals]for k,vals in v.items()}})\n expected=prod['cases']['base']['valuation']['value_per_share'] if name=='base' else prod['sensitivity']['gross_margin_minus_1pp']['valuation']['value_per_share']\n assert abs(float(v['0.1'][0])-expected)<1e-10\n if name=='base':\n  for rate in ['0.095','0.105']:\n   assert abs(float(v[rate][0])-prod['core'][rate]['value_per_share'])<1e-10\n   assert abs(float(v[rate][1])-prod['core'][rate]['terminal_year5_per_share'])<1e-10\nprint(json.dumps(checks,ensure_ascii=False,indent=2))\n", __file__, "exec"), {"__file__": __file__, "__name__": "__main__"})
